snippet.css:
.motion-example-linear { transition: transform 240ms cubic-bezier(0, 0, 1, 1); }
.motion-example-linear:hover { transform: translateX(24px); }
@media (prefers-reduced-motion: reduce) { .motion-example-linear { transition: none; transform: translateX(24px); } }

.motion-example-ease-in-out { transition: transform 320ms cubic-bezier(0.42, 0, 0.58, 1); }
.motion-example-ease-in-out:hover { transform: translateX(24px); }
@media (prefers-reduced-motion: reduce) { .motion-example-ease-in-out { transition: none; transform: translateX(24px); } }

.motion-example-spring.is-active { animation: motion-example-spring 500ms cubic-bezier(0.34, 1.56, 0.64, 1) 1 both; }
@keyframes motion-example-spring { from { transform: scale(.92); } to { transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .motion-example-spring.is-active { animation: none; transform: scale(1); } }

.motion-example-bounce.is-active { animation: motion-example-bounce 700ms linear(0 0%, 0.72 20%, 1.08 36%, 0.88 52%, 1.04 68%, 0.98 84%, 1 100%) 1 both; }
@keyframes motion-example-bounce { from { transform: scale(0); } to { transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .motion-example-bounce.is-active { animation: none; transform: scale(1); } }

.motion-example-elastic.is-active { animation: motion-example-elastic 900ms linear(0 0%, 1.22 18%, 0.86 32%, 1.1 46%, 0.94 60%, 1.04 74%, 0.98 88%, 1 100%) 1 both; }
@keyframes motion-example-elastic { from { transform: scale(0); } to { transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .motion-example-elastic.is-active { animation: none; transform: scale(1); } }

.motion-example-back { transition: transform 480ms cubic-bezier(0.68, -0.6, 0.32, 1.6); }
.motion-example-back:hover { transform: translateX(24px); }
@media (prefers-reduced-motion: reduce) { .motion-example-back { transition: none; transform: translateX(24px); } }

.motion-example-fade { opacity: 0; animation: motion-example-fade 220ms cubic-bezier(0.22, 1, 0.36, 1) 1 forwards; }
@keyframes motion-example-fade { to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .motion-example-fade { animation: none; opacity: 1; } }

.motion-example-slide { opacity: 0; transform: translateY(16px); animation: motion-example-slide 320ms cubic-bezier(0.22, 1, 0.36, 1) 1 forwards; }
@keyframes motion-example-slide { to { opacity: 1; transform: translateY(0); } }
@media (prefers-reduced-motion: reduce) { .motion-example-slide { animation: none; opacity: 1; transform: none; } }

.motion-example-scale { opacity: 0; transform: scale(.94); transform-origin: center; }
.motion-example-scale.is-open { opacity: 1; transform: scale(1); transition: transform 240ms cubic-bezier(0.34, 1.56, 0.64, 1), opacity 240ms cubic-bezier(0.34, 1.56, 0.64, 1); }
@media (prefers-reduced-motion: reduce) { .motion-example-scale.is-open { transition: none; opacity: 1; transform: scale(1); } }

.motion-example-blur-reveal { opacity: 0; filter: blur(12px); transform: translateY(8px); }
.motion-example-blur-reveal.is-visible { opacity: 1; filter: blur(0); transform: translateY(0); transition: filter 420ms cubic-bezier(0.22, 1, 0.36, 1), transform 420ms cubic-bezier(0.22, 1, 0.36, 1), opacity 420ms cubic-bezier(0.22, 1, 0.36, 1); }
@media (prefers-reduced-motion: reduce) { .motion-example-blur-reveal { transition: none; opacity: 1; filter: none; transform: none; } }

.motion-example-skeleton::after { content: ""; transform: translateX(-120%); animation: motion-example-shimmer 1200ms cubic-bezier(0.4, 0, 0.2, 1) infinite; }
@keyframes motion-example-shimmer { to { transform: translateX(220%); } }
@media (prefers-reduced-motion: reduce) { .motion-example-skeleton::after { animation: none; opacity: 0; } }

.motion-example-spinner { border: 3px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: motion-example-spin 800ms cubic-bezier(0.5, 0, 0.5, 1) infinite; }
@keyframes motion-example-spin { to { transform: rotate(1turn); } }
@media (prefers-reduced-motion: reduce) { .motion-example-spinner { animation: none; opacity: .75; } }

.motion-example-progress { overflow: hidden; background: #d9dcd5; }
.motion-example-progress > span {
  display: block; height: 8px; background: #242622;
  transform: scaleX(var(--progress, 0)); transform-origin: left;
  transition: transform 1600ms cubic-bezier(.65, 0, .35, 1);
}
@media (prefers-reduced-motion: reduce) {
  .motion-example-progress > span { transition: none; }
}

.motion-example-pulse { animation: motion-example-pulse 1200ms cubic-bezier(0.4, 0, 0.6, 1) infinite alternate; }
@keyframes motion-example-pulse { from { opacity: .55; transform: scale(.98); } to { opacity: 1; transform: scale(1); } }
@media (prefers-reduced-motion: reduce) { .motion-example-pulse { animation: none; opacity: 1; transform: scale(1); } }

.motion-example-scroll-timeline { transform: scaleX(1); transform-origin: left; }
@supports (animation-timeline: view()) { .motion-example-scroll-timeline { animation: motion-example-scroll-timeline cubic-bezier(0, 0, 1, 1) both; animation-timeline: view(); animation-range: entry 0% cover 100%; } @keyframes motion-example-scroll-timeline { from { transform: scaleX(0); } to { transform: scaleX(1); } } }
@media (prefers-reduced-motion: reduce) { .motion-example-scroll-timeline { animation: none; transform: scaleX(1); } }

.motion-example-scroll-reveal { opacity: 1; transform: none; }
.motion-example-scroll-reveal.is-observed {
  transition: opacity 420ms cubic-bezier(.22, 1, .36, 1),
              transform 420ms cubic-bezier(.22, 1, .36, 1);
}
.motion-example-scroll-reveal.is-observed:not(.is-visible) {
  opacity: 0; transform: translateY(16px);
}
@media (prefers-reduced-motion: reduce) {
  .motion-example-scroll-reveal.is-observed:not(.is-visible) {
    opacity: 1; transform: none;
  }
  .motion-example-scroll-reveal.is-observed { transition: none; }
}

reducedMotion.css:
@media (prefers-reduced-motion: reduce) {
  .motion-example-scroll-reveal.is-observed:not(.is-visible) {
    opacity: 1; transform: none;
  }
  .motion-example-scroll-reveal.is-observed { transition: none; }
}

snippet.css:
.motion-example-sticky { animation: motion-example-sticky cubic-bezier(0.42, 0, 0.58, 1) both; animation-timeline: view(); animation-range: 0px 240px; }
@keyframes motion-example-sticky { from { opacity: 1; transform: scale(1); } to { opacity: .7; transform: scale(.92); } }
@media (prefers-reduced-motion: reduce) { .motion-example-sticky { animation: none; opacity: 1; transform: none; } }

.motion-example-expand-collapse {
  display: grid; grid-template-rows: 0fr;
  transition: grid-template-rows 280ms cubic-bezier(.42, 0, .58, 1);
}
.motion-example-expand-collapse.is-open { grid-template-rows: 1fr; }
.motion-example-expand-collapse > div { min-height: 0; overflow: hidden; }
@media (prefers-reduced-motion: reduce) {
  .motion-example-expand-collapse { transition: none; }
}

.motion-example-tabs [role="tabpanel"][hidden] { display: none; }
.motion-example-tabs [role="tabpanel"]:not([hidden]) {
  animation: motion-tab-enter 220ms cubic-bezier(.22, 1, .36, 1);
}
@keyframes motion-tab-enter {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  .motion-example-tabs [role="tabpanel"]:not([hidden]) { animation: none; }
}

.motion-example-list-reorder > li {
  transition: transform 300ms cubic-bezier(.22, 1, .36, 1);
}
.motion-example-list-reorder > li.is-inverting {
  transform: translateY(var(--flip-y, 0px)); transition: none;
}
@media (prefers-reduced-motion: reduce) {
  .motion-example-list-reorder > li,
  .motion-example-list-reorder > li.is-inverting { transition: none; transform: none; }
}

reducedMotion.css:
@media (prefers-reduced-motion: reduce) {
  .motion-example-list-reorder > li,
  .motion-example-list-reorder > li.is-inverting { transition: none; transform: none; }
}
